CREATE TABLE pokedex (
    id SERIAL PRIMARY KEY,
    national_number BIGINT NOT NULL,
    name VARCHAR(50) NOT NULL,
    form_name VARCHAR(50) NOT NULL,
    gen VARCHAR(4) NOT NULL,
    primary_type VARCHAR(20) NOT NULL,
    secondary_type VARCHAR(20),
    evochain_0 VARCHAR(50) NOT NULL,
    evochain_1 VARCHAR(50),
    evochain_2 VARCHAR(50),
    evochain_3 VARCHAR(50),
    is_regional BOOLEAN NOT NULL,
    is_first_partner BOOLEAN NOT NULL,
    is_baby BOOLEAN NOT NULL,
    is_fossil BOOLEAN NOT NULL,
    is_sublegendary BOOLEAN NOT NULL,
    is_legendary BOOLEAN NOT NULL,
    is_mythical BOOLEAN NOT NULL,
    is_pseudo_legendary BOOLEAN,
    is_ultra_beast BOOLEAN NOT NULL,
    is_eeveelution BOOLEAN NOT NULL,
    image_url VARCHAR(255)
);

